{"content":"namespace LetUsCook.AutoWrongCensus.Models;

/// <summary>One HoldoutGate trace line, as written by <c>tools/LetUsCook.HoldoutGate</c>.</summary>
public sealed record TraceLine
{
	/// <summary>The raw recipe line as written.</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>Holdout recipe id, e.g. <c>debug:alisons-slow-cooker-vegetable-beef-s</c>.</summary>
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>Index of the ingredient line within the recipe.</summary>
	public int LineIndex { get; init; }

	/// <summary>The trace set: <c>debug</c> or <c>batch</c>. Anything else is refused (D-029).</summary>
	public string Set { get; init; } = string.Empty;

	/// <summary>Whether the line shipped to the household without review.</summary>
	public bool Auto { get; init; }

	/// <summary>Whether the accepted row matches the labelled key row.</summary>
	public bool Correct { get; init; }

	/// <summary>Labelled (key) FDC descriptions, the first being the key row.</summary>
	public IReadOnlyList<string> ExpectedDescriptions { get; init; } = [];

	/// <summary>Data-type tiers of the key rows.</summary>
	public IReadOnlyList<string> ExpectedDataTypes { get; init; } = [];

	/// <Descriptions of the rows the pipeline actually accepted.</Descriptions>
	/// <summary>Descriptions of the rows the pipeline actually accepted, the first being the accepted row.</summary>
	public IReadOnlyList<string> ActualDescriptions { get; init; } = [];

	/// <summary>Data-type tiers of the accepted rows.</summary>
	public IReadOnlyList<string> ActualDataTypes { get; init; } = [];

	/// <summary>Per-atom resolver outcomes; the census reads the first accepted atom.</summary>
	public IReadOnlyList<TraceAtom> Atoms { get; init; } = [];
}

/// <summary>One atom's resolver outcome inside a trace line.</summary>
public sealed record TraceAtom
{
	/// <summary>Decision path: <c>ranker</c>, <c>override</c>, or <c>curated</c>.</summary>
	public string Path { get; init; } = string.Empty;

	/// <summary>Whether the line reused an existing master row instead of fresh matching.</summary>
	public bool Reused { get; init; }

	/// <summary>The parsed ingredient name the resolver matched on.</summary>
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>Slug of the ingredient master the line linked to, when any.</summary>
	public string? LinkedIngredientId { get; init; }

	/// <summary>Atom outcome: <c>accepted</c>, <c>deferred</c>, or <c>rejected</c>.</summary>
	public string Outcome { get; init; } = string.Empty;
}
