{"content":"using System.Collections.Frozen;
using System.IO;
using System.Text.Json;

using LetUsCook.Fdc.Lexicon;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The raw-key set of <c>Lexicon/Resources/exact-overrides.json</c>, read from the embedded resource of
/// the production Fdc assembly — the same bytes the matcher ships with, so the census's
/// <c>overrideKey</c> column reflects the shipped file, not a copy (D-014).
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private readonly FrozenSet<string> _keys;

	/// <summary>Loads the shipped exact-overrides key set.</summary>
	/// <exception cref="InvalidOperationException">When the embedded resource is missing.</exception>
	public ExactOverrideKeyIndex()
	{
		var assembly = typeof(FdcNormalizer).Assembly;
		var name = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");
		using var reader = new StreamReader(stream);
		var entries = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(reader.ReadToEnd())
			?? throw new InvalidOperationException("exact-overrides.json was empty.");

		_keys = entries.Keys.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase).Keys.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Number of raw keys in the shipped file.</summary>
	public int Count => _keys.Count;

	/// <summary>Returns <see langword="true"/> when <paramref name="key"/> is a raw key of the file.</summary>
	/// <param name="key">The normalised raw line text.</param>
	public bool Contains(string key) => _keys.Contains(key);
}
