{"content":"using System.Text.Json;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The raw-key set of <c>Lexicon/Resources/exact-overrides.json</c>, read from the embedded resource of
/// the production <c>LetUsCook.Fdc</c> assembly — the same bytes the matcher ships with, no copy of the
/// file and no matching logic here (F-428 D-014).
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly HashSet<string> _keys;

	/// <summary>Loads the override key index from the embedded lexicon resource.</summary>
	/// <exception cref="InvalidOperationException">When the embedded resource is missing.</exception>
	public ExactOverrideKeyIndex()
	{
		var assembly = typeof(LetUsCook.Fdc.Lexicon.FdcNormalizer).Assembly;
		var name = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");

		var entries = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(stream, JsonOptions)
			?? throw new InvalidOperationException("exact-overrides.json was empty.");

		_keys = new HashSet<string>(entries.Keys, StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Returns <see langword="true"/> when <paramref name="key"/> is a raw key of the override file.</summary>
	/// <param name="key">The normalized raw line text.</param>
	public bool Contains(string key) => _keys.Contains(key);
}
