{"content":"using System.Text.RegularExpressions;

using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using LetUsCook.AutoWrongCensus.Models;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line (F-428 P12.13): the relation between the accepted row and the
/// labelled key row, and the site that accepted it. Every judgement goes through the production
/// helpers — <see cref="FdcNormalizer"/>, <see cref="FdcMatcher"/>'s state extraction,
/// <see cref="FdcDescriptionParser"/> and <see cref="IngredientLineResolver"/> — never a copy of them
/// (D-014). The relation ladder is evaluated in order; the first that holds wins.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the line has no labelled row.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw text, canned key state, accepted row not canned.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase is multi-word and the parsed name kept only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: head terms agree, state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree, dataset tier differs.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head and state and tier agree; the qualifiers differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms name different foods.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary>Relation: nothing above holds — the catch-all.</summary>
	public const string RelationOther = "other";

	/// <summary>Site: catalogue reuse on a ranker line.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact-override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker, not reused.</summary>
	public const string SiteRanker = "ranker";

	private static readonly FdcDataset[] NoDatasetHint = [];

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;
	private readonly List<string> _singleToken = new(1);

	/// <summary>Builds the classifier over the production normalizer and the shipped override key set.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">The embedded <c>exact-overrides.json</c> key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>Classifies one auto-wrong trace line.</summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The relation and site, with the audit fields for the TSV.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = line.Atoms.FirstOrDefault(a => string.Equals(a.Outcome, "accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();

		var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
		var acceptedDesc = line.ActualDescriptions.Count > 0 ? line.ActualDescriptions[0] : string.Empty;
		var keyTier = line.ExpectedDataTypes.Count > 0 ? line.ExpectedDataTypes[0] : string.Empty;
		var acceptedTier = line.ActualDataTypes.Count > 0 ? line.ActualDataTypes[0] : string.Empty;

		var site = string.Empty;
		var overrideKey = string.Empty;
		if (atom is not null)
		{
			switch (atom.Path)
			{
				case "override":
					site = SiteOverride;
					overrideKey = _overrideKeys.IsKey(FoldRawText(line.RawText)) ? "yes" : "no";
					break;
				case "curated":
					site = SiteCurated;
					break;
				case "ranker":
					site = atom.Reused ? SiteReuse : SiteRanker;
					break;
				default:
                    site = string.Empty;
                    break;
			}
		}

		var parsedTokens = atom is null ? [] : SingularizePhrase(atom.ParsedName);
		var keyHead = string.Empty;
		string relation;
		string? missingField = null;
		IReadOnlyList<string>? keyOnlyQualifiers = null;
		IReadOnlyList<string>? acceptedOnlyQualifiers = null;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = RelationNoLabel;
		}
		else
		{
			var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
            var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
            keyHead = string.Join(' ', KeyHeadPhrase(keyTokens));

            var keyState = CombinedState(keyTokens);
            var acceptedState = CombinedState(acceptedTokens);

            if (PackUnitRegex().IsMatch(line.RawText)
                && (keyState & FoodState.Canned) != 0
                && (acceptedState & FoodState.Canned) == 0)
            {
                relation = RelationPackUnitState;
            }
            else if (keyHead.Split(' ', StringSplitOptions.RemoveEmptyEntries).Length >= 2
                && parsedTokens.Count == 1
                && string.Equals(parsedTokens[0], IngredientLineResolver.SingularizeToken(keyHead.Split(' ')[0]), StringComparison.OrdinalIgnoreCase))
            {
                relation = RelationCompoundHeadLost;
            }
            else
            {
                var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
                var acceptedParsed = acceptedDesc.Length == 0
                    ? new ParsedFdcDescription(string.Empty, NoDatasetHint, null)
                    : FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));

                var keyHeadTokens = SingularizePhrase(keyParsed.HeadTerm);
                var acceptedHeadTokens = SingularizePhrase(acceptedParsed.HeadTerm);

                if (HeadsAgree(keyHeadTokens, acceptedHeadTokens))
                {
                    if (keyState != acceptedState)
                    {
                        relation = RelationStateMismatch;
                    }
                    else if (keyTier.Length == 0 || acceptedTier.Length == 0)
                    {
                        relation = RelationOther;
                        missingField = keyTier.Length == 0 ? "expectedDataTypes" : "actualDataTypes";
                    }
                    else if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
                    {
                        relation = RelationRowChoiceTier;
                    }
                    else
                    {
                        relation = RelationSameHeadOtherQualifier;
                        var keyQualifiers = QualifierSet(keyParsed.Qualifiers);
                        var acceptedQualifiers = QualifierSet(acceptedParsed.Qualifiers);
                        keyOnlyQualifiers = keyQualifiers.Except(acceptedQualifiers).OrderBy(q => q).ToList();
                        acceptedOnlyQualifiers = acceptedQualifiers.Except(keyQualifiers).OrderBy(q => q).ToList();
                    }
                }
                else
                {
                    relation = RelationSiblingFood;
                }
            }
        }

        return new ClassificationResult
        {
            HoldoutId = line.HoldoutId,
            LineIndex = line.LineIndex,
            Set = line.Set,
            Relation = relation,
            Site = site,
            OverrideKey = overrideKey,
            AcceptedTier = acceptedTier,
            KeyTier = keyTier,
            AcceptedState = acceptedState.ToString(),
            KeyState = keyState.ToString(),
            ParsedName = atom?.ParsedName ?? string.Empty,
            KeyHead = keyHead,
            AcceptedDesc = acceptedDesc,
            KeyDesc = keyDesc,
            RawText = line.RawText,
            MissingField = missingField,
            KeyOnlyQualifiers = keyOnlyQualifiers,
            AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
        };
    }

	/// <summary>
	/// The key description's head phrase: normalized tokens up to the first token production treats as
	/// a state or modifier word. <c>"Bread, crumbs, dry, grated, plain"</c> → <c>bread crumbs</c>;
	/// <c>"Tomatoes, crushed, canned"</c> → <c>tomato</c>. The stop test is production's own:
	/// <see cref="FdcLexicon.ModifierWords"/> plus <see cref="FdcMatcher"/>'s per-token state/satisfier
	/// extraction — no new word list (D-014).
	/// </summary>
	/// <param name="tokens">Normalized key-description tokens.</param>
	/// <returns>The leading head-phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		ArgumentNullException.ThrowIfNull(tokens);

		var lexicon = FdcLexicon.Default;
		var phrase = new List<string>(tokens.Count);
		foreach (var token in tokens)
		{
			if (IsStateOrModifierWord(lexicon, token))
			{
                return phrase;
            }

            phrase.Add(token);
        }

        return phrase;
    }

	/// <summary>State mask as production computes it: <see cref="FdcMatcher.ExtractCandidateState"/> ∪ <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>.</summary>
	/// <param name="tokens">Normalized candidate tokens.</param>
	/// <returns>The combined state mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens)
	{
		ArgumentNullException.ThrowIfNull(tokens);
		return FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);
	}

	/// <summary>Tier rank used for the row-choice summary: Foundation &gt; SrLegacy &gt; Survey &gt; Branded.</summary>
	/// <param name="tier">The dataset tier name from the trace.</param>
	/// <returns>The rank; 0 for an unrecognized tier.</returns>
	public static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
	};

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	private bool IsStateOrModifierWord(FdcLexicon lexicon, string token)
	{
		if (lexicon.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private IReadOnlyList<string> SingularizePhrase(string text)
	{
		return _normalizer.NormalizeToTokens(text)
			.Select(IngredientLineResolver.SingularizeToken)
			.ToList();
	}

	private static HashSet<string> QualifierSet(IReadOnlyList<string> qualifiers)
	{
		var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (var qualifier in qualifiers)
		{
			set.Add(IngredientLineResolver.SingularizeToken(qualifier));
		}

		return set;
	}

	private static bool HeadsAgree(IReadOnlyList<string> left, IReadOnlyList<string> right)
	{
		return left.SequenceEqual(right, StringComparer.OrdinalIgnoreCase);
	}

	// Production folds the raw text for the raw-key override lookup by dropping everything from the
	// first '(' (FdcMatcher.StripFromParenthesis, private — see the report note), then trimming and
	// lower-casing. This is that fold, applied to the key file the brief names.
	private static string FoldRawText(string rawText)
	{
		var text = rawText.Trim();
		var parenIndex = text.IndexOf('(', StringComparison.Ordinal);
		if (parenIndex >= 0)
		{
			text = text[..parenIndex];
		}

		return text.Trim().ToLowerInvariant();
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, out var dataset) ? dataset : FdcDataset.None;
}
