{"content":"using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using LetUsCook.AutoWrongCensus.Models;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes: the relation between the accepted row and the
/// labelled (key) row, and the decision site that accepted it (F-428 P12.13). Every judgement uses the
/// production helpers — <see cref="FdcNormalizer.NormalizeToTokens"/>, <see cref="FdcMatcher.ExtractCandidateState"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, <see cref="FdcDescriptionParser.Parse"/> and
/// <see cref="IngredientLineResolver.SingularizeToken"/> — never a local copy (D-014).
/// Not thread-safe: one instance per sequential census run.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the line carries no label row.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw text, canned key row, non-canned accepted row.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase is multi-word and the parsed name kept only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: head terms agree, state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree, dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head and state and tier agree; the qualifier tokens differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms name different foods.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: no class fits, or a field the classification needs is absent from the trace.</summary>
	public const string Other = "other";

	/// <summary>Site: catalogue reuse via the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: an exact-override hit.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue row.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: fresh ranker choice, no reuse.</summary>
	public const string SiteRanker = "ranker";

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;
	private readonly string?[] _singleTokenScratch = new string[1];

	/// <summary>Builds the classifier over the production normalizer and the shipped override key set.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">Keys of <c>exact-overrides.json</c>.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>
	/// Classifies one auto-wrong line. Returns a result with an empty <c>Site</c> when the atom's path is
	/// outside the known set, which the runner treats as a fatal instrument error.
	/// </summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The relation and site for the line.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line.Atoms.FirstOrDefault();
	 var keyDesc = FirstOrEmpty(line.ExpectedDescriptions);
		var keyType = FirstOrEmpty(line.ExpectedDataTypes);
		var acceptedDesc = FirstOrEmpty(line.ActualDescriptions);
		var acceptedType = FirstOrEmpty(line.ActualDataTypes);

		var site = SiteOf(atom);
		var overrideKey = site == SiteOverride ? (IsOverrideKey(line.RawText) ? "yes" : "no") : string.Empty;

		var base = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedType,
			KeyTier = keyType,
			ParsedName = atom?.ParsedName ?? string.Empty,
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return base with { Relation = NoLabel };
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyType));
		var acceptedParsed = string.IsNullOrWhiteSpace(acceptedDesc)
			? new ParsedFdcDescription(string.Empty, [], null)
			: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedType));

	 var keyHeadPhrase = KeyHeadPhrase(keyTokens);
		var keyHead = SingularizePhrase(keyHeadPhrase);
		var keyHeadTerm = SingularizeTokens(keyParsed.HeadTerm);
		var acceptedHeadTerm = SingularizeTokens(acceptedParsed.HeadTerm);
		var parsedNameTokens = SingularizeTokens(atom?.ParsedName);

		var result = base with { AcceptedState = acceptedState.ToString(), KeyState = keyState.ToString(), KeyHead = keyHead };

		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != 0
			&& (acceptedState & FoodState.Canned) == 0)
		{
			return result with { Relation = PackUnitState };
		}

		if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], keyHeadPhrase[0], StringComparison.OrdinalIgnoreCase))
		{
			return result with { Relation = CompoundHeadLost };
		}

		var headsAgree = keyHeadTerm.SequenceEqual(acceptedHeadTerm, StringComparer.OrdinalIgnoreCase);
		if (!headsAgree)
		{
			return result with { Relation = SiblingFood };
		}

		if (keyState != acceptedState)
		{
			return result with { Relation = StateMismatch };
		}

		if (string.IsNullOrEmpty(acceptedType) || string.IsNullOrEmpty(keyType))
		{
			return result with { Relation = Other, MissingField = string.IsNullOrEmpty(acceptedType) ? "actualDataTypes" : "expectedDataTypes" };
		}

		if (acceptedType != keyType)
		{
			return result with { Relation = RowChoiceTier };
		}

		var keyQualifiers = SortedDistinct(keyParsed.Qualifiers);
		var acceptedQualifiers = SortedDistinct(acceptedParsed.Qualifiers);
		return result with
		{
			Relation = SameHeadOtherQualifier,
			KeyOnlyQualifiers = keyQualifiers.Except(acceptedQualifiers).ToList(),
			AcceptedOnlyQualifiers = acceptedQualifiers.Except(keyQualifiers).ToList(),
		};
	}

	/// <summary>
	/// The key row's head phrase: the leading normalized tokens of the description, stopping before the
	/// first token production treats as a state or modifier word (<see cref="FdcLexicon.ModifierWords"/>
	/// or a token carrying a state/satisfier mask). "Bread, crumbs, dry, grated, plain" → [bread, crumbs];
	/// "Nuts, almonds, blanched" → [nut, almond].
	/// </summary>
	/// <param name="tokens">Normalized key-row tokens.</param>
	/// <returns>The head-phrase tokens, already singularised by the normalizer.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		ArgumentNullException.ThrowIfNull(tokens);

		var phrase = new List<string>(4);
		foreach (var token in tokens)
		{
			if (CarriesStateOrModifier(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>Folds raw text the way the matcher's override lookup does: lower-case, trimmed, content from the first <c>(</c> dropped.</summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The fold used for the <c>exact-overrides.json</c> key test.</returns>
	public static string FoldForOverrideKey(string rawText)
	{
		if (string.IsNullOrEmpty(rawText))
		{
			return string.Empty;
		}

		var paren = rawText.IndexOf('(', StringComparison.Ordinal);
		var text = paren >= 0 ? rawText[..paren] : rawText;
#pragma warning disable CA1308 // Reason: override keys are lowercase USDA-style text; parity with FdcMatcher's nameClean fold.
		return text.Trim().ToLowerInvariant();
#pragma warning restore CA1308
	}

	/// <summary>Tier rank per the curated-first order Foundation &gt; SrLegacy &gt; Survey &gt; Branded; 0 for unknown.</summary>
	/// <param name="tier">The dataset tier name.</param>
	/// <returns>The rank, higher is more curated.</returns>
	public static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
	};

	private bool IsOverrideKey(string rawText) => _overrideKeys.IsKey(FoldForOverrideKey(rawText));

	private static string SiteOf(TraceAtom? atom) => atom?.Path.ToLowerInvariant() switch
	{
		"override" => SiteOverride,
		"curated" => SiteCurated,
		"ranker" => atom!.Reused ? SiteReuse : SiteRanker,
		_ => string.Empty,
	};

	private bool CarriesStateOrModifier(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleTokenScratch[0] = token;
		return FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}

	private static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	private IReadOnlyList<string> SingularizeTokens(string? text)
	{
		var tokens = _normalizer.NormalizeToTokens(text);
		var result = new List<string>(tokens.Count);
		foreach (var token in tokens)
		{
			result.Add(IngredientLineResolver.SingularizeToken(token));
		}

		return result;
	}

	private static IReadOnlyList<string> SortedDistinct(IReadOnlyList<string> values)
	{
		var distinct = new SortedSet<string>(values, StringComparer.OrdinalIgnoreCase);
		return [.. distinct];
	}

	private static string SingularizePhrase(IReadOnlyList<string> tokens) => string.Join(' ', tokens);

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, out var dataset) ? dataset : FdcDataset.None;

	private static string FirstOrEmpty(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;
}
