{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>stdout/stderr sinks for one invocation; tests substitute string writers.</summary>
public sealed record OutputWriters(System.IO.TextWriter Output, System.IO.TextWriter Error);

/// <summary>
/// The census runner: reads a HoldoutGate trace, refuses any set other than <c>debug</c>/<c>batch</c>
/// (D-029), classifies every <c>auto &amp;&amp; !correct</c> line, and writes the relation×site TSV to
/// stdout with the summary on stderr.
/// </summary>
public sealed class AutoWrongCensusRunner : IAutoWrongCensusRunner
{
	/// <summary>Trace sets the instrument is allowed to read.</summary>
	public static readonly IReadOnlySet<string> AllowedSets = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "debug", "batch" };

	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly IOptions<AutoWrongCensusOptions> _options;
	private readonly AutoWrongClassifier _classifier;
	private readonly FdcNormalizer _normalizer;
	private readonly OutputWriters _writers;

	/// <summary>Creates the runner.</summary>
	/// <param name="options">Bound CLI options.</param>
	/// <param name="classifier">The production-helper-backed classifier.</param>
	/// <param name="normalizer">The production normalizer (used by the <c>pairs</c> head fold).</param>
	/// <param name="writers">Output/error sinks.</param>
	public AutoWrongCensusRunner(
		IOptions<AutoWrongCensusOptions> options,
		AutoWrongClassifier classifier,
		FdcNormalizer normalizer,
		OutputWriters writers)
	{
		ArgumentNullException.ThrowIfNull(options);
		ArgumentNullException.ThrowIfNull(classifier);
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(writers);
		_options = options;
		_classifier = classifier;
		_normalizer = normalizer;
		_writers = writers;
	}

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var options = _options.Value;
		switch (options.Command.ToLowerInvariant())
		{
			case CommandLineArgumentParser.CensusCommand:
				return await RunCensusAsync(options.TracePath, cancellationToken).ConfigureAwait(false);
			case CommandLineArgumentParser.PairsCommand:
				return await RunPairsAsync(options.CensusTsvPath, options.TracePath, cancellationToken).ConfigureAwait(false);
			default:
				_writers.Error.WriteLine("AutoWrongCensus: unusable arguments. Expected 'census <trace.jsonl>' or 'pairs <census.tsv> <trace.jsonl>' (see --help).");
				return 1;
		}
	}

	/// <summary>Classifies every auto-wrong line of one trace and writes the census TSV.</summary>
	/// <param name="tracePath">The trace JSONL path.</param>
	/// <param name="cancellationToken">Shutdown token.</param>
	/// <returns>0 on success; 1 on a missing file, refused set, or unknown atom path.</returns>
	private async Task<int> RunCensusAsync(string tracePath, CancellationToken cancellationToken)
	{
		if (string.IsNullOrWhiteSpace(tracePath) || !File.Exists(tracePath))
		{
			_writers.Error.WriteLine($"AutoWrongCensus: trace file not found: '{tracePath}'.");
			return 1;
		}

		var lines = ReadTrace(tracePath, cancellationToken);
		if (lines is null)
		{
			return 1;
		}

		var results = new List<ClassificationResult>();
		foreach (var line in lines)
		{
			if (cancellationToken.IsCancellationRequested)
			{
				return 1;
			}

			if (!line.Auto || line.Correct)
			{
				continue;
			}

			var result = _classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				_writers.Error.WriteLine($"AutoWrongCensus: unknown atom path '{AtomPathOf(line)}' on {line.HoldoutId}#{line.LineIndex}; refusing to guess a site.");
				return 1;
			}

			results.Add(result);
		}

		_writers.Output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var result in results)
		{
			_writers.Output.WriteLine(string.Join('\t',
				Sanitize(result.HoldoutId), result.LineIndex.ToString(), Sanitize(result.Set), Sanitize(result.Relation), Sanitize(result.Site),
				Sanitize(result.OverrideKey), Sanitize(result.AcceptedTier), Sanitize(result.KeyTier),
				Sanitize(result.AcceptedState), Sanitize(result.KeyState), Sanitize(result.ParsedName),
				Sanitize(result.KeyHead), Sanitize(result.AcceptedDesc), Sanitize(result.KeyDesc), Sanitize(result.RawText)));
		}

		WriteSummary(lines.Count, results);
		return 0;
	}

	/// <summary>
	/// Emits the parsedName-head vs key-head pairs for every P12.7 census row with
	/// <c>blocker=window</c> and <c>route</c> in {compound, other}, joined with the trace.
	/// </summary>
	/// <param name="censusTsvPath">The P12.7 blocker-census TSV.</param>
	/// <param name="tracePath">The matching debug trace JSONL.</param>
	/// <param name="cancellationToken">Shutdown token.</param>
	/// <returns>0 on success; 1 on missing files, refused set, or malformed census.</returns>
	private async Task<int> RunPairsAsync(string censusTsvPath, string tracePath, CancellationToken cancellationToken)
	{
		if (string.IsNullOrWhiteSpace(censusTsvPath) || !File.Exists(censusTsvPath))
		{
			_writers.Error.WriteLine($"AutoWrongCensus: census TSV not found: '{censusTsvPath}'.");
			return 1;
		}

		if (string.IsNullOrWhiteSpace(tracePath) || !File.Exists(tracePath))
		{
			_writers.Error.WriteLine($"AutoWrongCensus: trace file not found: '{tracePath}'.");
			return 1;
		}

		var lines = ReadTrace(tracePath, cancellationToken);
		if (lines is null)
		{
			return 1;
		}

		var byKey = new Dictionary<(string, int), TraceLine>(lines.Count);
		foreach (var line in lines)
		{
			byKey.TryAdd((line.HoldoutId, line.LineIndex), line);
		}

		var censusLines = File.ReadAllLines(censusTsvPath);
		if (censusLines.Length == 0)
		{
			_writers.Error.WriteLine($"AutoWrongCensus: census TSV '{censusTsvPath}' is empty.");
			return 1;
		}

		var header = censusLines[0].Split('\t');
		var col = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
		for (var i = 0; i < header.Length; i++)
		{
			col[header[i]] = i;
		}

		foreach (var required in new[] { "holdoutId", "lineIndex", "blocker", "route" })
		{
			if (!col.ContainsKey(required))
			{
				_writers.Error.WriteLine($"AutoWrongCensus: census TSV '{censusTsvPath}' is missing column '{required}'.");
				return 1;
			}
		}

		var emitted = 0;
		var missingInTrace = 0;
		_writers.Output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		for (var i = 1; i < censusLines.Length; i++)
		{
			if (cancellationToken.IsCancellationRequested)
			{
				return 1;
			}

			var columns = censusLines[i].Split('\t');
			if (columns.Length <= col["blocker"] || columns[col["blocker"]] != "window")
			{
				continue;
			}

			var route = columns.Length > col["route"] ? columns[col["route"]] : string.Empty;
			if (route != "compound" && route != "other")
			{
				continue;
            }

			var holdoutId = columns[col["holdoutId"]];
			if (!int.TryParse(columns[col["lineIndex"]], out var lineIndex))
			{
				_writers.Error.WriteLine($"AutoWrongCensus: census row {i} has a non-integer lineIndex '{columns[col["lineIndex"]]}'.");
                return 1;
            }

            var traceLine = byKey.TryGetValue((holdoutId, lineIndex), out var found) ? found : null;
            if (traceLine is null)
            {
                missingInTrace++;
                continue;
            }

            var atom = traceLine.Atoms.Count > 0 ? traceLine.Atoms[0] : null;
            var parsedNameHead = atom is null ? string.Empty : string.Join(' ', FoldTokens(_normalizer.NormalizeToTokens(atom.ParsedName)));
            var keyHead = _classifier.KeyHeadPhrase(_normalizer.NormalizeToTokens(First(traceLine.ExpectedDescriptions)));

            _writers.Output.WriteLine(string.Join('\t',
                Sanitize(holdoutId), lineIndex.ToString(), Sanitize(parsedNameHead), Sanitize(string.Join(' ', keyHead)), Sanitize(traceLine.RawText)));
            emitted++;
        }

        _writers.Error.WriteLine($"pairs: censusRows={censusLines.Length - 1} windowCompoundOther={emitted} missingInTrace={missingInTrace}");
        return 0;
    }

	private List<TraceLine>? ReadTrace(string tracePath, CancellationToken cancellationToken)
	{
		var lines = new List<TraceLine>();
		var lineNumber = 0;
		foreach (var raw in File.ReadAllLines(tracePath))
		{
			if (cancellationToken.IsCancellationRequested)
			{
                return null;
            }

            lineNumber++;
            if (string.IsNullOrWhiteSpace(raw))
            {
                continue;
            }

            TraceLine? line;
            try
            {
                line = JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions);
            }
            catch (JsonException ex)
            {
                _writers.Error.WriteLine($"AutoWrongCensus: malformed trace line {lineNumber} in '{tracePath}': {ex.Message}");
                return null;
            }

            if (line is null)
            {
                _writers.Error.WriteLine($"AutoWrongCensus: empty trace line {lineNumber} in '{tracePath}'.");
                return null;
            }

            if (!AllowedSets.Contains(line.Set))
            {
                _writers.Error.WriteLine($"AutoWrongCensus: refusing trace: set '{line.Set}' is not debug/batch (D-029).");
                return null;
            }

            lines.Add(line);
        }

        return lines;
    }

	private void WriteSummary(int tracedLines, IReadOnlyList<ClassificationResult> results)
	{
		var set = results.Count > 0 ? results[0].Set : "unknown";
		_writers.Error.WriteLine($"autoWrongCensus set={set} tracedLines={tracedLines} autoWrong={results.Count}");

		var matrix = results
			.GroupBy(r => (r.Relation, r.Site))
			.OrderBy(g => g.Key.Item1, StringComparer.Ordinal)
			.ThenBy(g => g.Key.Item2, StringComparer.Ordinal);
	 _writers.Error.WriteLine("relation\tsite\tcount");
		foreach (var group in matrix)
		{
			_writers.Error.WriteLine($"{group.Key.Item1}\t{group.Key.Item2}\t{group.Count()}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		_writers.Error.WriteLine($"other share: {other}/{results.Count} ({results.Count > 0 ? other * 100.0 / results.Count : 0.0:F1}%)");

		var missingFields = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField!);
		_writers.Error.WriteLine(missingFields.Any()
			? "missing fields: " + string.Join(", ", missingFields.Select(g => $"{g.Key}={g.Count()}"))
			: "missing fields: none");

		var overrideYes = results.Count(r => r.Site == AutoWrongClassifier.SiteOverride && r.OverrideKey == "yes");
		var overrideNo = results.Count(r => r.Site == AutoWrongClassifier.SiteOverride && r.OverrideKey == "no");
		_writers.Error.WriteLine($"override raw-key hits: yes={overrideYes} no={overrideNo}");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseFail = reuseLines.Count(r => r.ParsedName.Length > 0 && r.KeyDesc.Length > 0 && !ShouldReuseAgainstKey(r));
		_writers.Error.WriteLine($"reuse lines where ShouldReuse(parsedName, key-row phrase) is false: {reuseFail} of {reuseLines.Count}");

		var tierRows = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier);
		var keyHigher = tierRows.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
		var acceptedHigher = tierRows.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier));
		_writers.Error.WriteLine($"row-choice-tier: key tier higher={keyHigher} accepted tier higher={acceptedHigher}");

		var qualifierRows = results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier && (r.KeyOnlyQualifiers?.Count > 0 || r.AcceptedOnlyQualifiers?.Count > 0));
		if (qualifierRows.Any())
		{
			_writers.Error.WriteLine("same-head-other-qualifier qualifier diffs:");
			foreach (var row in qualifierRows)
            {
                _writers.Error.WriteLine($"  {row.HoldoutId}#{row.LineIndex}\tkeyOnly=[{string.Join(',', row.KeyOnlyQualifiers ?? [])}]\tacceptedOnly=[{string.Join(',', row.AcceptedOnlyQualifiers ?? [])}]");
            }
        }
	}

	// The resolver's own exact-phrase reuse rule applied to the key row: would the production
	// ShouldReuse(computedSlug, keySlug) have linked this line to the key row's food?
	private static bool ShouldReuseAgainstKey(ClassificationResult row)
	{
		var keySlug = string.Join('-', FoldTokensRaw(row.KeyDesc));
		return IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(row.ParsedName), keySlug);
	}

	private static IReadOnlyList<string> FoldTokens(IReadOnlyList<string> tokens) =>
		Array.ConvertAll(tokens.ToArray(), t => IngredientLineResolver.SingularizeToken(t));

	private static IReadOnlyList<string> FoldTokensRaw(string text)
	{
		var folded = new List<string>();
		foreach (var token in text.Split(new[] { ',', ' ' }, StringSplitOptions.RemoveEmptyEntries))
		{
			folded.Add(IngredientLineResolver.SingularizeToken(token.ToLowerInvariant()));
		}

		return folded;
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string AtomPathOf(TraceLine line) => line.Atoms.Count > 0 ? line.Atoms[0].Path : string.Empty;

	private static string Sanitize(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;
}
