using Shouldly;

using Xunit;

namespace LetUsCook.AutoWrongCensus.Tests.Options;

public sealed class CommandLineArgumentParserTests
{
	[Fact]
	public void ParseMapsCensusSubcommand()
	{
		var result = CommandLineArgumentParser.Parse(["census", "trace.jsonl"]);

		result["AutoWrongCensus:Command"].ShouldBe("census");
		result["AutoWrongCensus:TracePath"].ShouldBe("trace.jsonl");
	}

	[Fact]
	public void ParseMapsPairsSubcommandWithBothPaths()
	{
		var result = CommandLineArgumentParser.Parse(["pairs", "census.tsv", "trace.jsonl"]);

		result["AutoWrongCensus:Command"].ShouldBe("pairs");
		result["AutoWrongCensus:CensusTsvPath"].ShouldBe("census.tsv");
		result["AutoWrongCensus:TracePath"].ShouldBe("trace.jsonl");
	}

	[Fact]
	public void ParseReturnsEmptyForUnusableArguments()
	{
		CommandLineArgumentParser.Parse([]).ShouldBeEmpty();
		CommandLineArgumentParser.Parse(["census"]).ShouldBeEmpty();
		CommandLineArgumentParser.Parse(["census", "a", "b"]).ShouldBeEmpty();
		CommandLineArgumentParser.Parse(["pairs", "only-one"]).ShouldBeEmpty();
		CommandLineArgumentParser.Parse(["bogus", "trace.jsonl"]).ShouldBeEmpty();
	}
}
