	private static TraceLine Line(string holdoutId, string set) =>
		new()
		{
			RawText = "1 thing",
			HoldoutId = holdoutId,
			LineIndex = 0,
			Set = set,
			Auto = true,
			Correct = false,
			ExpectedDescriptions = ["Something, raw"],
			ExpectedDataTypes = ["Foundation"],
			ActualDescriptions = ["Other thing, raw"],
			ActualDataTypes = ["SrLegacy"],
			Atoms = [new TraceAtom { Path = "ranker", ParsedName = "thing", Outcome = "accepted" }],
		};

	private static string WriteTrace(IEnumerable<TraceLine> lines) =>
		WriteText(lines.Select(l => JsonSerializer.Serialize(l, JsonOptions)));

	private static string WriteText(IEnumerable<string> lines)
	{
		var path = Path.Combine(Path.GetTempPath(), $"autowrong-f428-{Guid.NewGuid():N}.txt");
		File.WriteAllLines(path, lines);
		return path;
	}
