	[Fact]
	public void AWordyKeyDescriptionWithNoHeadTailInRawTextIsNotCompoundHeadLost()
	{
		var line = Line(
			rawText: "2 cups flour",
			keyDescriptions: ["Flour, wheat, all-purpose, enriched, bleached"],
			keyTypes: ["SrLegacy"],
			acceptedDescriptions: ["Flour, wheat, all-purpose, enriched, bleached"],
			acceptedTypes: ["Foundation"],
			path: "ranker",
			reused: true,
			parsedName: "flour",
			linked: "flour");

		var result = Classifier.Classify(line);

		result.Relation.ShouldNotBe(AutoWrongClassifier.RelationCompoundHeadLost);
		result.Relation.ShouldBe(AutoWrongClassifier.RelationRowChoiceTier);
	}

	[Fact]
	public void AHeadTailNamedInRawTextWithAOneWordParsedNameIsCompoundHeadLost()
	{
		var line = Line(
			rawText: "1 cup chopped water chestnuts",
			keyDescriptions: ["Water chestnuts, raw"],
			keyTypes: ["SrLegacy"],
			acceptedDescriptions: ["Water chestnuts, canned"],
			acceptedTypes: ["SrLegacy"],
			path: "override",
			reused: true,
			parsedName: "water");

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationCompoundHeadLost);
		result.KeyHead.ShouldBe("water chestnut");
	}

	[Fact]
	public void ACanUnitWithANonCannedKeyIsNotPackUnitState()
	{
		var line = Line(
			rawText: "1 can coconut cream",
			keyDescriptions: ["Oils, coconut"],
			keyTypes: ["SrLegacy"],
			acceptedDescriptions: ["Oils, coconut"],
			acceptedTypes: ["SrLegacy"],
			path: "ranker",
			reused: true,
			parsedName: "coconut cream",
			linked: "oil");

		var result = Classifier.Classify(line);

		result.Relation.ShouldBe(AutoWrongClassifier.RelationSameHeadOtherQualifier);
	}

