	public void OverrideKeyFoldingIgnoresTextAfterAParenthesis()
	{
		var line = Line(
			rawText: "amaretto (or amaretto liqueur)",
			keyDescriptions: ["Cherries, sour, red"],
			keyTypes: ["SrLegacy"],
