def sing(r):
    # approximation of production SingularizeToken: strip common plural suffixes
    if r.endswith('ies') and len(r)>3: return r[:-3]+'y'
    if r.endswith('ves'): return r[:-3]+'f'
    if r.endswith('es') and len(r)>2: return r[:-2]
    if r.endswith('s') and not r.endswith('ss'): return r[:-1]
    return r
def head_tail_in_raw(head, raw):
    raw_s = {sing(w) for w in words(raw)}
    for t in head[1:]:
